import React, { useState, useEffect } from "react";
import {
  Box,
  Tabs,
  Tab,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  Paper,
  Button,
  TextField,
  Typography,
  TablePagination,
  CircularProgress,
  IconButton,
  InputAdornment,
  Grid,
} from "@mui/material";
import {
  Store as StoreIcon,
  AddLocationAlt as AddOutletIcon,
  Edit as EditIcon,
  Delete as DeleteIcon,
  Search,
} from "@mui/icons-material";
import Swal from "sweetalert2";
import { apiRequest } from "../utils/apiRequest";
import { API } from "../api/endpoints";
import {
  buildOutletPayload,
  getOutletSecondaryPhone,
} from "../utils/outletApi";

function TabPanel({ children, value, index, ...other }) {
  return (
    <div
      role="tabpanel"
      hidden={value !== index}
      id={`outlet-tabpanel-${index}`}
      aria-labelledby={`outlet-tab-${index}`}
      {...other}
    >
      {value === index && <Box sx={{ p: 3 }}>{children}</Box>}
    </div>
  );
}

const Outlet = () => {
  const [tabValue, setTabValue] = useState(0);
  const [searchQuery, setSearchQuery] = useState("");
  const [outlets, setOutlets] = useState([]);
  const [page, setPage] = useState(0);
  const [rowsPerPage, setRowsPerPage] = useState(10);
  const [totalOutlets, setTotalOutlets] = useState(0);
  const [loading, setLoading] = useState(false);
  const [editMode, setEditMode] = useState(false);
  const [selectedOutletId, setSelectedOutletId] = useState(null);
  const [buttonLoading, setButtonLoading] = useState(false);
  const [formData, setFormData] = useState({
    name: "",
    email: "",
    phone: "",
    secondary_phone: "",
  });
  const [errors, setErrors] = useState({});

  const token =
    typeof window !== "undefined" ? localStorage.getItem("token") : null;

  const Toast = Swal.mixin({
    toast: true,
    position: "top-end",
    showConfirmButton: false,
    timer: 1500,
    timerProgressBar: true,
    didOpen: (toast) => {
      toast.addEventListener("mouseenter", Swal.stopTimer);
      toast.addEventListener("mouseleave", Swal.resumeTimer);
    },
    customClass: {
      container: "swal-toast-container",
      popup: "swal-toast-popup",
    },
  });

  useEffect(() => {
    const styleSheet = document.createElement("style");
    styleSheet.textContent = `
      .swal-toast-container {
        z-index: 9999 !important;
      }
      .swal-toast-popup {
        font-family: 'Inter', sans-serif;
        font-size: 14px;
      }
    `;
    document.head.appendChild(styleSheet);
    return () => document.head.removeChild(styleSheet);
  }, []);

  const fetchOutlets = async () => {
    setLoading(true);
    try {
      const response = await apiRequest({
        ...API.outletsList,
        params: {
          paginate: true,
          page: page + 1,
          per_page: rowsPerPage,
          search: searchQuery,
        },
      });
      setOutlets(response?.data?.data || []);
      setTotalOutlets(response?.data?.total || 0);
    } catch (error) {
      setOutlets([]);
      setTotalOutlets(0);
      console.error("Error fetching outlets:", error);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchOutlets();
  }, [page, rowsPerPage, searchQuery]);

  const handleTabChange = (event, newValue) => {
    setTabValue(newValue);
    setEditMode(false);
    setSelectedOutletId(null);
    setFormData({
      name: "",
      email: "",
      phone: "",
      secondary_phone: "",
    });
    setErrors({});
  };

  const handleInputChange = (event) => {
    const { name, value } = event.target;
    setFormData((prev) => ({ ...prev, [name]: value }));
    setErrors((prev) => ({ ...prev, [name]: "" }));
  };

  const validateForm = () => {
    const newErrors = {};
    if (!formData.name.trim()) newErrors.name = "Name is required";
    if (!formData.email.trim()) newErrors.email = "Email is required";
    else if (!/\S+@\S+\.\S+/.test(formData.email))
      newErrors.email = "Invalid email format";
    if (!formData.phone.trim()) newErrors.phone = "Outlet phone is required";
    setErrors(newErrors);
    return Object.keys(newErrors).length === 0;
  };

  const handleSaveChanges = async () => {
    if (!validateForm()) return;

    setButtonLoading(true);

    const payload = buildOutletPayload(formData);

    try {
      const response = await apiRequest({
        ...(editMode
          ? { ...API.editOutlet(selectedOutletId) }
          : { ...API.addOutlet }),
        method: "POST",
        data: payload,
      });

      Toast.fire({
        icon: "success",
        title:
          response?.message || (editMode ? "Outlet updated" : "Outlet added"),
      });

      setTabValue(0);
      fetchOutlets();
      handleCancel();
    } catch (error) {
      Toast.fire({
        icon: "error",
        title: error?.message || "Failed to save outlet",
      });
    } finally {
      setButtonLoading(false);
    }
  };

  const handleCancel = () => {
    setEditMode(false);
    setSelectedOutletId(null);
    setFormData({
      name: "",
      email: "",
      phone: "",
      secondary_phone: "",
    });
    setErrors({});
  };

  const handleEdit = async (id) => {
    try {
      const response = await apiRequest({ ...API.outletDetails(id) });
      const row = response?.data;

      setFormData({
        name: row?.name || "",
        email: row?.email || "",
        phone: row?.phone || "",
        secondary_phone: getOutletSecondaryPhone(row),
      });

      setSelectedOutletId(id);
      setEditMode(true);
      setTabValue(1);
    } catch (error) {
      Toast.fire({
        icon: "error",
        title: error?.message || "Failed to fetch outlet details",
      });
    }
  };

  const handleDelete = (id) => {
    Swal.fire({
      title: "Are you sure?",
      text: "You won't be able to revert this!",
      icon: "warning",
      showCancelButton: true,
      confirmButtonColor: "#43B02A",
      cancelButtonColor: "#C92A20",
      confirmButtonText: "Yes, delete it!",
      cancelButtonText: "No, cancel",
      customClass: {
        container: "swal-toast-container",
        popup: "swal-toast-popup",
      },
    }).then(async (result) => {
      if (result.isConfirmed) {
        try {
          const response = await apiRequest({
            ...API.deleteOutlet(id),
          });

          Toast.fire({
            icon: "success",
            title: response?.message || "Outlet deleted successfully",
          });

          fetchOutlets();
        } catch (error) {
          Toast.fire({
            icon: "error",
            title: error?.message || "Failed to delete outlet",
          });
        }
      }
    });
  };

  const handleChangePage = (event, newPage) => {
    setPage(newPage);
  };

  const handleChangeRowsPerPage = (event) => {
    setRowsPerPage(parseInt(event.target.value, 10));
    setPage(0);
  };

  return (
    <Grid container>
      <Box sx={{ mb: 2, width: "100%" }}>
        <TextField
          placeholder="Search outlets..."
          value={searchQuery}
          onChange={(e) => {
            setSearchQuery(e.target.value);
            setPage(0);
          }}
          size="small"
          sx={{
            "& .MuiOutlinedInput-root": {
              borderRadius: 8,
              backgroundColor: "#fff",
              "& fieldset": { borderColor: "#e0e0e0" },
              "&:hover fieldset": { borderColor: "#bdbdbd" },
              "&.Mui-focused fieldset": { borderColor: "#4CAF50" },
              "& input": {
                padding: { xs: "6px 10px", sm: "8px 12px" },
                fontSize: { xs: "0.75rem", sm: "0.875rem" },
              },
            },
          }}
          InputProps={{
            startAdornment: (
              <InputAdornment position="start">
                <Search sx={{ color: "#666", fontSize: { xs: 18, sm: 20 } }} />
              </InputAdornment>
            ),
          }}
        />
      </Box>

      <Paper
        sx={{
          width: "100%",
          borderRadius: 2,
          boxShadow: 1,
          overflow: "hidden",
        }}
      >
        <Box sx={{ borderBottom: "1px solid #e0e0e0" }}>
          <Tabs
            value={tabValue}
            onChange={handleTabChange}
            sx={{
              "& .MuiTab-root": {
                textTransform: "none",
                fontWeight: 500,
                minHeight: 48,
                borderRadius: 1,
              },
              "& .Mui-selected": {
                backgroundColor: "#F97316 !important",
                color: "white !important",
              },
              "& .MuiTabs-indicator": { backgroundColor: "#fff", height: 2 },
            }}
          >
            <Tab
              icon={<StoreIcon />}
              label="Outlet List"
              iconPosition="start"
              sx={{ gap: 1 }}
            />
            <Tab
              icon={editMode ? <EditIcon /> : <AddOutletIcon />}
              label={editMode ? "Update Outlet" : "Add Outlet"}
              iconPosition="start"
              sx={{ gap: 1 }}
            />
          </Tabs>
        </Box>

        <TabPanel value={tabValue} index={0}>
          <TableContainer>
            <Table>
              <TableHead>
                <TableRow>
                  <TableCell sx={{ fontWeight: "bold" }}>ID</TableCell>
                  <TableCell sx={{ fontWeight: "bold" }}>Outlet Name</TableCell>
                  <TableCell sx={{ fontWeight: "bold" }}>
                    Outlet Email
                  </TableCell>
                  <TableCell sx={{ fontWeight: "bold" }}>
                    Outlet Phone
                  </TableCell>
                  <TableCell sx={{ fontWeight: "bold" }}>
                    Secondary / Mobile
                  </TableCell>
                  <TableCell sx={{ fontWeight: "bold" }}>Actions</TableCell>
                </TableRow>
              </TableHead>
              <TableBody>
                {loading ? (
                  <TableRow>
                    <TableCell colSpan={6} align="center">
                      Loading...
                    </TableCell>
                  </TableRow>
                ) : Array.isArray(outlets) && outlets.length > 0 ? (
                  outlets.map((outlet) => (
                    <TableRow
                      key={outlet.id}
                      sx={{ "&:hover": { backgroundColor: "#f9f9f9" } }}
                    >
                      <TableCell>{outlet.id}</TableCell>
                      <TableCell>{outlet.name}</TableCell>
                      <TableCell>{outlet.email || "N/A"}</TableCell>
                      <TableCell>{outlet.phone || "N/A"}</TableCell>
                      <TableCell>
                        {getOutletSecondaryPhone(outlet) || "N/A"}
                      </TableCell>
                      <TableCell>
                        <Box sx={{ display: "flex", gap: 1 }}>
                          <Button
                            variant="contained"
                            size="small"
                            onClick={() => handleEdit(outlet.id)}
                            sx={{
                              backgroundColor: "#3B82F6",
                              "&:hover": { backgroundColor: "#3B82F6" },
                              textTransform: "none",
                              borderRadius: 3,
                              fontSize: "12px",
                              lineHeight: 1.5,
                            }}
                          >
                            Edit
                          </Button>
                          <IconButton
                            size="small"
                            onClick={() => handleDelete(outlet.id)}
                            sx={{
                              backgroundColor: "#C92A20",
                              "&:hover": { backgroundColor: "#b12419" },
                              color: "#fff",
                              width: "32px",
                              height: "32px",
                            }}
                          >
                            <DeleteIcon fontSize="small" />
                          </IconButton>
                        </Box>
                      </TableCell>
                    </TableRow>
                  ))
                ) : (
                  <TableRow>
                    <TableCell colSpan={6} align="center">
                      No data available
                    </TableCell>
                  </TableRow>
                )}
              </TableBody>
            </Table>
          </TableContainer>
          <TablePagination
            rowsPerPageOptions={[5, 10, 25]}
            component="div"
            count={totalOutlets}
            rowsPerPage={rowsPerPage}
            page={page}
            onPageChange={handleChangePage}
            onRowsPerPageChange={handleChangeRowsPerPage}
          />
        </TabPanel>

        <TabPanel value={tabValue} index={1}>
          <Box sx={{ maxWidth: 600, mx: "auto" }}>
            <Typography
              variant="subtitle1"
              sx={{ mb: 1, fontWeight: "medium" }}
            >
              Outlet Name
            </Typography>
            <TextField
              fullWidth
              name="name"
              placeholder="Outlet / store name"
              value={formData.name}
              onChange={handleInputChange}
              variant="outlined"
              size="small"
              error={!!errors.name}
              helperText={errors.name}
              sx={{
                "& .MuiOutlinedInput-root": { borderRadius: "4px" },
                mb: 2,
              }}
            />

            <Typography
              variant="subtitle1"
              sx={{ mb: 1, fontWeight: "medium" }}
            >
              Outlet Email
            </Typography>
            <TextField
              fullWidth
              name="email"
              type="email"
              placeholder="contact@outlet.example"
              value={formData.email}
              onChange={handleInputChange}
              variant="outlined"
              size="small"
              error={!!errors.email}
              helperText={errors.email}
              sx={{
                "& .MuiOutlinedInput-root": { borderRadius: "4px" },
                mb: 2,
              }}
            />

            <Typography
              variant="subtitle1"
              sx={{ mb: 1, fontWeight: "medium" }}
            >
              Outlet Phone
            </Typography>
            <TextField
              fullWidth
              name="phone"
              placeholder="Store phone number"
              value={formData.phone}
              onChange={handleInputChange}
              variant="outlined"
              size="small"
              error={!!errors.phone}
              helperText={errors.phone}
              sx={{
                "& .MuiOutlinedInput-root": { borderRadius: "4px" },
                mb: 2,
              }}
            />

            <Typography
              variant="subtitle1"
              sx={{ mb: 1, fontWeight: "medium" }}
            >
              Secondary / Mobile (optional)
            </Typography>
            <TextField
              fullWidth
              name="secondary_phone"
              placeholder="Optional secondary or mobile number"
              value={formData.secondary_phone}
              onChange={handleInputChange}
              variant="outlined"
              size="small"
              sx={{
                "& .MuiOutlinedInput-root": { borderRadius: "4px" },
                mb: 2,
              }}
            />

            <Box sx={{ display: "flex", gap: 2, justifyContent: "flex-end" }}>
              <Button
                variant="contained"
                onClick={handleSaveChanges}
                disabled={buttonLoading}
                sx={{
                  backgroundColor: "#43B02A",
                  "&:hover": { backgroundColor: "#3a9624" },
                  textTransform: "none",
                  px: 3,
                  display: "flex",
                  alignItems: "center",
                  gap: 1,
                }}
              >
                {buttonLoading && (
                  <CircularProgress size={20} sx={{ color: "white" }} />
                )}
                {editMode ? "Update Outlet" : "Save Changes"}
              </Button>
              <Button
                variant="contained"
                onClick={handleCancel}
                sx={{
                  backgroundColor: "#C92A20",
                  "&:hover": { backgroundColor: "#b12419" },
                  textTransform: "none",
                  px: 3,
                }}
              >
                Cancel
              </Button>
            </Box>
          </Box>
        </TabPanel>
      </Paper>
    </Grid>
  );
};

export default Outlet;
